window.__NICE_DATA_GZ='';
(async()=>{
 try{
  const bytes=Uint8Array.from(atob(window.__NICE_DATA_GZ),c=>c.charCodeAt(0));
  if(typeof DecompressionStream!=='function') throw new Error('Este navegador não suporta DecompressionStream. Atualize o navegador.');
  const ds=new DecompressionStream('gzip');
  const stream=new Blob([bytes]).stream().pipeThrough(ds);
  window.__NICE_DATA=await new Response(stream).text();
  JSON.parse(window.__NICE_DATA);
  const s=document.createElement('script');
  s.src='app.js?v=4'; s.defer=false;
  document.body.appendChild(s);
 }catch(err){
  console.error('Falha ao carregar dados NICE:',err);
  document.querySelectorAll('.kpi strong').forEach(el=>el.textContent='ERRO');
  const box=document.createElement('div');
  box.style='max-width:1200px;margin:20px auto;padding:16px;border:1px solid #ef4444;background:#fff1f2;color:#991b1b;border-radius:10px;font:14px Segoe UI,Arial';
  box.textContent='Erro ao carregar a base de dados. Recarregue com Ctrl+F5. Detalhe: '+err.message;
  document.body.prepend(box);
 }
})();
